-- Schema for the Dungeon Escape stats database (SQLite).
-- Applied on every startup; every statement is idempotent.
-- Timestamps are ISO 8601 UTC strings ("2026-10-16T12:34:56Z").

CREATE TABLE IF NOT EXISTS players (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    name       TEXT    NOT NULL UNIQUE COLLATE NOCASE,
    created_at TEXT    NOT NULL
);

-- Run ids are generated by the game (32 hex chars) so that it can queue
-- requests offline and retry them without creating duplicates.
CREATE TABLE IF NOT EXISTS runs (
    id             TEXT    PRIMARY KEY,
    player_id      INTEGER NOT NULL REFERENCES players(id),
    mode           TEXT    NOT NULL DEFAULT 'normal' CHECK (mode IN ('normal', 'test', 'demo')),
    run_seed       INTEGER NOT NULL DEFAULT 0,
    start_level    INTEGER NOT NULL DEFAULT 1,
    started_at     TEXT    NOT NULL,
    ended_at       TEXT,
    level_reached  INTEGER NOT NULL DEFAULT 1,
    score          INTEGER NOT NULL DEFAULT 0,
    enemies_killed INTEGER NOT NULL DEFAULT 0,
    outcome        TEXT    NOT NULL DEFAULT 'in_progress'
                           CHECK (outcome IN ('died', 'quit', 'in_progress')),
    duration_s     REAL    NOT NULL DEFAULT 0
);

CREATE INDEX IF NOT EXISTS idx_runs_score ON runs(score);
CREATE INDEX IF NOT EXISTS idx_runs_player ON runs(player_id);

-- Events accept any type, so new kinds (for example coins) need no migration.
-- (run_id, seq) is unique: a retried batch never inserts an event twice.
CREATE TABLE IF NOT EXISTS events (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    run_id     TEXT    NOT NULL REFERENCES runs(id) ON DELETE CASCADE,
    seq        INTEGER NOT NULL,
    type       TEXT    NOT NULL,
    level      INTEGER,
    t_run_s    REAL    NOT NULL DEFAULT 0,
    payload    TEXT    NOT NULL DEFAULT '{}',
    created_at TEXT    NOT NULL,
    UNIQUE (run_id, seq)
);

CREATE INDEX IF NOT EXISTS idx_events_run ON events(run_id);
CREATE INDEX IF NOT EXISTS idx_events_type ON events(type);

-- One row per level played, uploaded by the game after its Telemetry autoload
-- writes the level file (route, events and map; see docs/analitica.md).
-- (run_id, level, attempt) is unique: re-uploading a file changes nothing.
-- data keeps the whole JSON file; the other columns are copies for filtering.
CREATE TABLE IF NOT EXISTS level_tracks (
    id               INTEGER PRIMARY KEY AUTOINCREMENT,
    run_id           TEXT    NOT NULL REFERENCES runs(id) ON DELETE CASCADE,
    level            INTEGER NOT NULL,
    attempt          INTEGER NOT NULL DEFAULT 1,
    mode             TEXT    NOT NULL DEFAULT 'normal',
    game_version     TEXT    NOT NULL DEFAULT '',
    outcome          TEXT    NOT NULL,
    duration_s       REAL    NOT NULL DEFAULT 0,
    map_key          TEXT    NOT NULL DEFAULT '',
    difficulty_index REAL,
    data             TEXT    NOT NULL,
    received_at      TEXT    NOT NULL,
    UNIQUE (run_id, level, attempt)
);

CREATE INDEX IF NOT EXISTS idx_level_tracks_run ON level_tracks(run_id);
CREATE INDEX IF NOT EXISTS idx_level_tracks_level ON level_tracks(level);
